int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int i;
    for (i = 0; i < len; i++) {
        unsigned char byte = p[i];

        if (byte == 0x00) {
            break;
        }

        switch (byte & 0xC0) {
            case 0x00:
                facilities->random_value = byte & 0x3F;
                break;
            case 0x40:
                facilities->source_digipeater[facilities->num_source_digipeaters++] = byte & 0x3F;
                break;
            case 0x80:
                facilities->dest_digipeater[facilities->num_dest_digipeaters++] = byte & 0x3F;
                break;
            case 0xC0:
                if (facilities->num_failure_calls < ROSE_MAX_FAILURE_CALLS) {
                    facilities->failure_calls[facilities->num_failure_calls++] = byte & 0x3F;
                }
                break;
        }

        if ((byte & 0x80) == 0xC0) {
            i++;
            if (i < len) {
                facilities->address = p[i];
            }
        }
    }

    return i;
}

int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;

    while (processed < len && p[processed] != 0x00) {
        unsigned char byte = p[processed++];
        unsigned char facility_type = (byte >> 6) & 0x03;

        switch (facility_type) {
            case 0x00: // Random value facility
                facilities->random_value = p[processed];
                processed++;
                break;

            case 0x01: // Source digipeater
                facilities->source_digipeater[facilities->num_digipeaters++] = p[processed];
                processed++;
                break;

            case 0x02: // Destination digipeater
                facilities->dest_digipeater[facilities->num_digipeaters++] = p[processed];
                processed++;
                break;

            case 0x03: // Failure call
                memcpy(facilities->failure_call, &p[processed], 7);
                processed += 7;
                break;

            default:
                // Unknown facility type, skip the byte
                break;
        }
    }

    return processed;
}

int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int i = 0;
    unsigned char c;

    while (i < len) {
        c = p[i];

        if (c == 0x00) {
            break; /* Termination byte encountered */
        }

        switch (c & 0xC0) {
            case 0x00: /* Random value facility */
                facilities->random_value = c & 0x3F;
                break;
            case 0x40: /* Source digipeater facility */
                facilities->source_digipeater = c & 0x3F;
                break;
            case 0x80: /* Destination digipeater facility */
                facilities->dest_digipeater = c & 0x3F;
                break;
            case 0xC0: /* Failure call or address facility */
                facilities->failure_call = c & 0x3F;
                break;
        }

        i++;
    }

    return i;
}

int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int bytes_processed = 0;

    while (bytes_processed < len && p[bytes_processed] != 0x00) {
        unsigned char facility_type = p[bytes_processed] >> 6;

        switch (facility_type) {
        case 0: // Random value
            facilities->random_value = p[bytes_processed + 1];
            bytes_processed += 2;
            break;
        case 1: // Source digipeater
            facilities->source_digipeater = p[bytes_processed + 1];
            bytes_processed += 2;
            break;
        case 2: // Destination digipeater
            facilities->dest_digipeater = p[bytes_processed + 1];
            bytes_processed += 2;
            break;
        case 3: // Failure call
            facilities->failure_call = p[bytes_processed + 1];
            bytes_processed += 2;
            break;
        default:
            // Skip unknown facility type
            bytes_processed++;
            break;
        }
    }

    // Account for the termination byte if it is within the given length
    if (bytes_processed < len && p[bytes_processed] == 0x00) {
        bytes_processed++;
    }

    return bytes_processed;
}

int parse_national_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int i = 0;
    unsigned char facility_type;

    while (i < len && p[i] != 0x00) {
        facility_type = (p[i] >> 6) & 0x03;

        switch (facility_type) {
            case 0:
                // Random facility
                facilities->random_facility = p[i + 1];
                i += 2;
                break;
            case 1:
                // Source Digipeater
                facilities->source_digipeater[facilities->num_source_digipeaters++] = p[i + 1];
                i += 2;
                break;
            case 2:
                // Destination Digipeater
                facilities->dest_digipeater[facilities->num_dest_digipeaters++] = p[i + 1];
                i += 2;
                break;
            case 3:
                // Failure Call
                facilities->failure_call[facilities->num_failure_calls++] = p[i + 1];
                i += 2;
                break;
            default:
                // Unknown facility type
                i += 1;
                break;
        }
    }

    return i + 1;  // Include the terminating byte in the count
}
